        if (l > r || r > size()) {
            throw std::out_of_range("RollingHash: substring range");
        }
    }

    void check_base(const RollingHash& other) const {
        if (base_ != other.base_) {
            throw std::invalid_argument("RollingHash: different bases");
        }
    }
#endif
